#include <stdio.h>
#include <stdlib.h>
#include <math.h>

#define MAXN 20
#define INF 1e18

int N, T, E;
double p[MAXN];
double dp[MAXN][MAXN][2]; // min time, at left or right, all done for [l..r]

// ... complex DP

#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

static int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll*)a;
    ll y = *(const ll*)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

static ll maxll(ll a, ll b) { return a > b ? a : b; }
static ll minll(ll a, ll b) { return a < b ? a : b; }

int main(void) {
    int N;
    ll E, T;
    if (scanf("%d %lld %lld", &N, &E, &T) != 3) return 0;

    ll *x = (ll*)malloc(sizeof(ll) * N);
    for (int i = 0; i < N; ++i) scanf("%lld", &x[i]);

    qsort(x, N, sizeof(ll), cmp_ll);

    /* Split bears into left (<0), zero (=0), right (>0) */
    int lcnt = 0, rcnt = 0, zcnt = 0;
    for (int i = 0; i < N; ++i) {
        if (x[i] < 0) lcnt++;
        else if (x[i] > 0) rcnt++;
        else zcnt++;
    }

    ll *L = (ll*)malloc(sizeof(ll) * (lcnt + 1)); /* positive distances from 0, increasing */
    ll *R = (ll*)malloc(sizeof(ll) * (rcnt + 1)); /* positions >0, increasing */

    for (int i = 0; i < lcnt; ++i) L[i + 1] = -x[lcnt - i - 1];
    for (int i = 0; i < rcnt; ++i) R[i + 1] = x[lcnt + zcnt + i];

    /*
      For one side only:
      Need to visit all bears on that side, but coin at distance d can only be collected
      at time >= first_visit_time(d) + T.
      If we go monotonically outward and finish at farthest point M, minimum finish time is:
         max( M, max_i (2*d_i + T - d_i) ) = max(M, max_i(d_i + T)) = M + T
      if there is at least one bear on that side.
      More generally, if starting from 0 and ending back at 0 after clearing one side:
         farthest m => m out, maybe wait, then return => 2m + T.
      These formulas are embedded in transitions below.
    */

    const ll INF = (1LL << 62);

    /*
      dpL[i][j]: minimum time after all bears among first i on left and first j on right
      have been given candies and all corresponding coins collected, and current position is
      at left point -L[i] (if i>0) or 0 (if i=0 and state valid).
      Similarly dpR[i][j] at right point R[j].
    */
    ll **dpL = (ll**)malloc((lcnt + 1) * sizeof(ll*));
    ll **dpR = (ll**)malloc((lcnt + 1) * sizeof(ll*));
    for (int i = 0; i <= lcnt; ++i) {
        dpL[i] = (ll*)malloc((rcnt + 1) * sizeof(ll));
        dpR[i] = (ll*)malloc((rcnt + 1) * sizeof(ll));
        for (int j = 0; j <= rcnt; ++j) dpL[i][j] = dpR[i][j] = INF;
    }

    /* Initial state at origin after handling all zero-position bears:
       give candies at t=0, collect zero coins at time T, still at 0. */
    dpL[0][0] = dpR[0][0] = T * (zcnt > 0);

    for (int i = 0; i <= lcnt; ++i) {
        for (int j = 0; j <= rcnt; ++j) {
            if (i == 0 && j == 0) continue;

            /* Compute dpL[i][j] */
            if (i > 0) {
                /* from dpL[i-1][j] moving further left */
                if (dpL[i - 1][j] < INF) {
                    ll prevPos = (i - 1 == 0 ? 0 : -L[i - 1]);
                    ll curPos = -L[i];
                    ll arr = dpL[i - 1][j] + llabs(curPos - prevPos);
                    /* Need coin of bear i ready by arrival or wait there; since this is farthest left so far,
                       all previous collected already. First visit to this bear is now. Need wait T then can collect immediately. */
                    arr = maxll(arr, arr + T); /* simplified below */
                    /* Actually must wait T after giving candy now */
                    arr = dpL[i - 1][j] + llabs(curPos - prevPos) + T;
                    dpL[i][j] = minll(dpL[i][j], arr);
                }
                /* from dpR[i-1? no], from dpR[i-1?][j] crossing from right/0 to this new left bear */
                if (dpR[i - 1][j] < INF) {
                    ll prevPos = (j == 0 ? 0 : R[j]);
                    ll curPos = -L[i];
                    ll arr = dpR[i - 1][j] + llabs(curPos - prevPos) + T;
                    dpL[i][j] = minll(dpL[i][j], arr);
                }
            }

            /* Compute dpR[i][j] */
            if (j > 0) {
                if (dpR[i][j - 1] < INF) {
                    ll prevPos = (j - 1 == 0 ? 0 : R[j - 1]);
                    ll curPos = R[j];
                    ll arr = dpR[i][j - 1] + llabs(curPos - prevPos) + T;
                    dpR[i][j] = minll(dpR[i][j], arr);
                }
                if (dpL[i][j - 1] < INF) {
                    ll prevPos = (i == 0 ? 0 : -L[i]);
                    ll curPos = R[j];
                    ll arr = dpL[i][j - 1] + llabs(curPos - prevPos) + T;
                    dpR[i][j] = minll(dpR[i][j], arr);
                }
            }
        }
    }

    /*
      The above DP is too pessimistic if we always force waiting T at every newly visited bear.
      But on a line, optimal strategy is:
      choose an order of first visits; collection can be delayed and merged.
      In fact, after visiting a new extreme point p, extra time needed due to its coin is only that
      final completion time must be at least first_visit(p)+T, not immediate waiting.
      Therefore we instead compute based on total path length and latest(first_visit+T).

      For a state covering left i and right j, ending on left:
      total walked length if ending on left and having visited both extremes:
        if i==0: impossible except origin
        else if j==0: L[i]
        else: 2*R[j] + L[i]   or 2*L[i] + R[j], depending on order.
      We need minimum final time = max(path_length, max_first_visit_plus_T).
      On a line, optimal first-visit schedule for covered interval [-L[i], R[j]] ending on left is:
        either go left first then all way to right then back to left: length 2*R[j]+L[i],
             first visits: left side at their distances, right side after 2*left? not optimal for right first-visit times
        or right first then left then back...
      We can derive closed forms by two possible orders.
    */

    ll ans = INF;

    /* Helper to update answer for each of 4 patterns:
       1) only left
       2) only right
       3) left first, then right, end exit side by direct move
       4) right first, then left, ...
    */

    if (lcnt == 0 && rcnt == 0) {
        ans = T * (zcnt > 0) + llabs(E);
        printf("%lld\n", ans);
        return 0;
    }

    /* Enumerate final side-order patterns exactly. */

    /* Only left side exists/handled */
    if (rcnt == 0) {
        ll m = L[lcnt];
        ll finishAtLeft = m + T;
        ans = minll(ans, finishAtLeft + llabs(E + m));
    }

    /* Only right side */
    if (lcnt == 0) {
        ll m = R[rcnt];
        ll finishAtRight = m + T;
        ans = minll(ans, finishAtRight + llabs(E - m));
    }

    if (lcnt > 0 && rcnt > 0) {
        ll a = L[lcnt], b = R[rcnt];

        /*
          Order A: go to left extreme first, then to right extreme, then maybe end anywhere on segment/path.
          First visit times:
            left bear at distance d visited at time d
            right bear at position r first visited at time 2*a + r
          If final endpoint after covering all is at right extreme:
            path length = 2*a + b
            need time >= max(2*a+b, max(a+T, 2*a+b+T)) = 2*a+b+T
          Similarly ending at left after left->right->left: 2*(a+b)+T.
          So once both sides exist, if last newly visited side is right and we end at right extreme, finish time is 2*a+b+T.
        */
        ll finishRight_afterLeftFirst = 2 * a + b + T;
        ll finishLeft_afterRightFirst = 2 * b + a + T;

        ans = minll(ans, finishRight_afterLeftFirst + llabs(E - b));
        ans = minll(ans, finishLeft_afterRightFirst + llabs(E + a));

        /* If after visiting both extremes we pass beyond and exit lies on the way, direct formula:
           from right extreme to exit */
        /* already covered by |E-b|, similarly left */

        /*
          Could end not at an extreme after collecting all coins? No, after all coins collected and all bears visited,
          any point between extremes would require having moved from one extreme inward, so equivalent to ending at an
          extreme then moving inward; |E-extreme| handles that.
        */
    }

    /* Zero-position bears may force initial wait T if any exist, but when there are non-zero bears,
       that wait can overlap with travel. So we must incorporate them correctly:
       Need overall completion time >= T as well.
       Add by taking max with T to all derived completion times before going to exit.
    */
    ll zwait = (zcnt > 0 ? T : 0);

    ll best = INF;

    if (lcnt == 0 && rcnt == 0) {
        best = zwait + llabs(E);
    } else if (rcnt == 0) {
        ll m = L[lcnt];
        ll finish = maxll(m + T, zwait);
        best = minll(best, finish + llabs(E + m));
    } else if (lcnt == 0) {
        ll m = R[rcnt];
        ll finish = maxll(m + T, zwait);
        best = minll(best, finish + llabs(E - m));
    } else {
        ll a = L[lcnt], b = R[rcnt];
        ll finishR = maxll(2 * a + b + T, zwait);
        ll finishL = maxll(2 * b + a + T, zwait);
        best = minll(best, finishR + llabs(E - b));
        best = minll(best, finishL + llabs(E + a));
    }

    printf("%lld\n", best);

    for (int i = 0; i <= lcnt; ++i) {
        free(dpL[i]);
        free(dpR[i]);
    }
    free(dpL);
    free(dpR);
    free(x);
    free(L);
    free(R);
    return 0;
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int T = sc.nextInt();
        int E = sc.nextInt();
        int[] x = new int[N];
        for (int i = 0; i < N; i++) {
            x[i] = sc.nextInt();
        }

        // dp[mask][i] = min time to have given candies to set 'mask'
        // and end at position of bear i (last given candy)
        double INF = 1e18;
        double[][] dp = new double[1 << N][N];
        for (double[] row : dp) Arrays.fill(row, INF);

        // Initialize: start at position 0, go to first bear
        for (int i = 0; i < N; i++) {
            dp[1 << i][i] = Math.abs(x[i]); // time to reach bear i from 0
        }

        // DP over masks
        for (int mask = 1; mask < (1 << N); mask++) {
            for (int last = 0; last < N; last++) {
                if ((mask & (1 << last)) == 0) continue;
                if (dp[mask][last] >= INF) continue;
                double curTime = dp[mask][last];
                // Try to give candy to next bear
                for (int next = 0; next < N; next++) {
                    if ((mask & (1 << next)) != 0) continue;
                    int newMask = mask | (1 << next);
                    double arriveTime = curTime + Math.abs(x[last] - x[next]);
                    if (arriveTime < dp[newMask][next]) {
                        dp[newMask][next] = arriveTime;
                    }
                }
            }
        }

        double answer = INF;
        int fullMask = (1 << N) - 1;

        // For each possible ending bear after giving all candies
        for (int last = 0; last < N; last++) {
            if (dp[fullMask][last] >= INF) continue;
            double giveEndTime = dp[fullMask][last];

            // Now we need to collect all coins.
            // Each coin at x[i] becomes available at giveTime[i] + T.
            // We need to find minimal time to visit all coin positions and then go to E.
            // We can treat this as traveling salesman with release times.

            // First compute give times from the path:
            // We can reconstruct the order from DP, but simpler: 
            // We'll compute minimal additional time from state (giveEndTime, pos = x[last])
            // to collect all coins and go to exit.
            // Since N ≤ 15, we can do another DP for coin collection.

            // Compute giveTime for each bear along the optimal path for this ending.
            // We'll reconstruct path by storing predecessor.
            // But here we can just compute by iterating over subsets again with known give times.
            // Instead, we'll compute minimal collection time using DP over subsets of collected coins.

            // We'll do DP2[mask][i] = min time to have collected coins of set mask,
            // ending at position of bear i

            double[][] dp2 = new double[1 << N][N];
            for (double[] row : dp2) Arrays.fill(row, INF);

            // We don't know give times exactly without path, but we can compute them
            // from the DP1 by storing parent info. Simpler: brute force over all permutations
            // for the giving order that achieve dp[fullMask][last] and get give times.
            // But N=15, 15! is too big. So we store parent in DP1.
            // Let's modify DP1 to store parent.
        }

        // Since storing parent makes code longer, here's alternative simpler approach:
        // We'll do DP that simultaneously tracks giving and collecting, 
        // but state includes which coins are already collected.

        // State: dp[maskG][maskC][i] = min time, having given to maskG, collected maskC, at bear i
        // maskC subset of maskG (can't collect before giving)
        // Complexity: 3^N * N^2 maybe okay for N=15 (3^15 = 14 million, times 225 ~ 3.2B too high)

        // Better: Since after giving all candies, we just need to collect all coins and go to exit,
        // we can compute minimal time for collecting given release times.
        // We can compute release times for each bear from the giving order.
        // We'll store predecessor in DP1 to reconstruct.

        int[][] parent = new int[1 << N][N];
        double[][] dpFinal = new double[1 << N][N];
        for (double[] row : dpFinal) Arrays.fill(row, INF);
        for (int i = 0; i < N; i++) {
            dpFinal[1 << i][i] = Math.abs(x[i]);
            parent[1 << i][i] = -1;
        }
        for (int mask = 1; mask < (1 << N); mask++) {
            for (int last = 0; last < N; last++) {
                if ((mask & (1 << last)) == 0) continue;
                if (dpFinal[mask][last] >= INF) continue;
                double cur = dpFinal[mask][last];
                for (int next = 0; next < N; next++) {
                    if ((mask & (1 << next)) != 0) continue;
                    int nmask = mask | (1 << next);
                    double ntime = cur + Math.abs(x[last] - x[next]);
                    if (ntime < dpFinal[nmask][next]) {
                        dpFinal[nmask][next] = ntime;
                        parent[nmask][next] = last;
                    }
                }
            }
        }

        // For each possible last bear, reconstruct give times
        for (int last = 0; last < N; last++) {
            if (dpFinal[fullMask][last] >= INF) continue;
            double[] giveTime = new double[N];
            int mask = fullMask;
            int cur = last;
            double time = dpFinal[fullMask][last];
            // reconstruct backwards
            while (mask != 0) {
                giveTime[cur] = time;
                int prev = parent[mask][cur];
                if (prev == -1) {
                    // first bear
                    giveTime[cur] = Math.abs(x[cur]);
                    break;
                }
                time -= Math.abs(x[cur] - x[prev]);
                mask ^= (1 << cur);
                cur = prev;
            }
            // Now we have give times, compute coin collection
            // DP for collecting coins
            double[][] collectDP = new double[1 << N][N];
            for (double[] row : collectDP) Arrays.fill(row, INF);
            // start from position x[last] at time dpFinal[fullMask][last]
            for (int i = 0; i < N; i++) {
                double arrive = dpFinal[fullMask][last] + Math.abs(x[last] - x[i]);
                double release = giveTime[i] + T;
                double collectTime = Math.max(arrive, release);
                collectDP[1 << i][i] = collectTime;
            }
            for (int cmask = 1; cmask < (1 << N); cmask++) {
                for (int i = 0; i < N; i++) {
                    if ((cmask & (1 << i)) == 0) continue;
                    if (collectDP[cmask][i] >= INF) continue;
                    double curTime = collectDP[cmask][i];
                    for (int j = 0; j < N; j++) {
                        if ((cmask & (1 << j)) != 0) continue;
                        int nmask = cmask | (1 << j);
                        double arrive = curTime + Math.abs(x[i] - x[j]);
                        double release = giveTime[j] + T;
                        double ntime = Math.max(arrive, release);
                        if (ntime < collectDP[nmask][j]) {
                            collectDP[nmask][j] = ntime;
                        }
                    }
                }
            }
            for (int i = 0; i < N; i++) {
                if (collectDP[fullMask][i] >= INF) continue;
                double total = collectDP[fullMask][i] + Math.abs(x[i] - E);
                if (total < answer) answer = total;
            }
        }

        System.out.printf("%.10f\n", answer);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static long abs(long x) {
        return x >= 0 ? x : -x;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt();
        long E = fs.nextLong();
        long T = fs.nextLong();

        long[] x = new long[N];
        for (int i = 0; i < N; i++) x[i] = fs.nextLong();

        Arrays.sort(x);

        if (N == 0) {
            System.out.println(abs(E));
            return;
        }

        int split = 0;
        while (split < N && x[split] < 0) split++;

        int L = split;       // negatives
        int R = N - split;   // non-negatives

        long[] left = new long[L + 1];   // distances on left, increasing away from 0
        for (int i = 1; i <= L; i++) left[i] = -x[L - i];

        long[] right = new long[R + 1];
        for (int i = 1; i <= R; i++) right[i] = x[split + i - 1];

        long INF = Long.MAX_VALUE / 4;

        // dpL[i][j]: minimal time after giving candies to first i left bears and first j right bears,
        // and currently at left position left[i] (i>0, or at 0 if i=0 but we won't use final state there specially)
        // dpR similarly at right position right[j].
        long[][] dpL = new long[L + 1][R + 1];
        long[][] dpR = new long[L + 1][R + 1];
        for (int i = 0; i <= L; i++) {
            Arrays.fill(dpL[i], INF);
            Arrays.fill(dpR[i], INF);
        }

        dpL[0][0] = dpR[0][0] = 0;

        for (int i = 0; i <= L; i++) {
            for (int j = 0; j <= R; j++) {
                long curL = dpL[i][j];
                if (curL < INF) {
                    long pos = (i == 0 ? 0 : -left[i]);

                    if (i < L) {
                        long npos = -left[i + 1];
                        dpL[i + 1][j] = Math.min(dpL[i + 1][j], curL + abs(pos - npos));
                    }
                    if (j < R) {
                        long npos = right[j + 1];
                        dpR[i][j + 1] = Math.min(dpR[i][j + 1], curL + abs(pos - npos));
                    }
                }

                long curR = dpR[i][j];
                if (curR < INF) {
                    long pos = (j == 0 ? 0 : right[j]);

                    if (i < L) {
                        long npos = -left[i + 1];
                        dpL[i + 1][j] = Math.min(dpL[i + 1][j], curR + abs(pos - npos));
                    }
                    if (j < R) {
                        long npos = right[j + 1];
                        dpR[i][j + 1] = Math.min(dpR[i][j + 1], curR + abs(pos - npos));
                    }
                }
            }
        }

        // After all candies are given, all coins appear no later than finishGiving + T.
        // Since coins are at the same bear positions, after that moment we need to traverse all bear positions
        // and end at E. Starting point is the position of the last bear visited when giving candies.
        //
        // Let interval be [Lmost, Rmost] where bears exist.
        // To collect all coins after time W, starting from s and ending at E, minimal additional travel is:
        // min(
        //   dist(s, leftEnd) + (rightEnd-leftEnd) + dist(E, rightEnd),
        //   dist(s, rightEnd) + (rightEnd-leftEnd) + dist(E, leftEnd)
        // )
